package StringPrograms;

public class StartsWithCheck {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String s1 = "Red is favorite color.";
        String s2 = "Orange is also my favorite color.";

        System.out.println(s1 + " starts with Red? " + s1.startsWith("Red"));
        System.out.println(s2 + " starts with Red? " + s2.startsWith("Red"));
	}

}
